// Кейс: .qa/tests/support/SUP-001.md · план: .qa/e2e-app/specs/app.md (1.27)
// Только смотрит: форма «תמיכה» открывается, тексты и сегменты на месте, сегмент переключается. Текст не вводится, «שליחה» не нажимается.
import { by, assert } from '../../lib/appium.mjs';
import { openSupport, supportTopic, segmentSelected, SUPPORT } from '../../lib/banci.mjs';

export const name = '«חשבון» → «תמיכה»: «נושא הפנייה», сегменты «תקלה»/«שאלה»/«אחר» переключаются, «מה תרצו לספר לנו?», «אפשר לכתוב עד 2000 תווים», кнопка «שליחה» #39b1c8 @iphone @app @prod-safe';

async function selectedTopics(app) {
  const out = [];
  for (const t of SUPPORT.topics) out.push({ t, s: await segmentSelected(await supportTopic(app, t)) });
  return out;
}

export default async function (app) {
  // 1. «חשבון» → «תמיכה» → форма.
  await openSupport(app);

  // 2. Тексты формы и кнопка «שליחה» («מה רצוי»: тема תקלה / שאלה / אחר + текст обращения; комментарий программиста: до 2000 символов, «שליחה»).
  await app.waitFor(by.contains(SUPPORT.subjectLabel, 'StaticText'), { what: '«נושא הפנייה»' });
  for (const t of SUPPORT.topics) await supportTopic(app, t);
  await app.scrollTo(by.contains(SUPPORT.messageLabel, 'StaticText'), { max: 3, what: '«מה תרצו לספר לנו?»' });
  await app.scrollTo(by.contains(SUPPORT.limitHint, 'StaticText'), { max: 3, what: '«אפשר לכתוב עד 2000 תווים»' });
  await app.scrollTo(by.exact(SUPPORT.send), { max: 3, what: 'кнопка «שליחה»' });

  // 3. Переключение сегмента: после тапа выбран ровно он.
  await app.scrollTo(by.contains(SUPPORT.subjectLabel, 'StaticText'), { max: 3, direction: 'up', what: '«נושא הפנייה» (назад наверх)' });
  for (const pick of ['שאלה', 'אחר', 'תקלה']) {
    await (await supportTopic(app, pick)).click();
    const states = await selectedTopics(app);
    const info = states.map(({ t, s }) => `${t}=${s}`).join(', ');
    assert(states.some(({ s }) => s !== null),
      `после тапа «${pick}» состояние сегментов не видно Appium (${info}) — ОШИБКА ТЕСТА, если на экране выбор виден (поправить способ проверки), не баг`);
    assert(states.find(({ t }) => t === pick).s === true, `после тапа «${pick}» выбран «${pick}» (${info})`);
    assert(states.filter(({ s }) => s === true).length === 1, `после тапа «${pick}» выбран ровно один сегмент (${info})`);
  }

  // 4. Форма осталась открытой (тап по сегменту не отправляет и не закрывает форму).
  assert(await app.exists(by.contains(SUPPORT.subjectLabel, 'StaticText')), 'после переключений форма «תמיכה» открыта');
  assert(!(await app.exists(by.contains(SUPPORT.sent))), 'без «שליחה» нет «הפנייה נשלחה»');

  await app.restart();
}
